//! Purpose:
//! AST builders for PHP's `ext/zip` surface: the `ZipArchive` class, the deprecated
//! procedural `zip_*` functions, and the two user-space stream wrappers.
//!
//! Called from:
//! - `crate::zip_prelude::zip_declarations()`.
//!
//! Key details:
//! - Generated by `synthetic_class::transcribe` from `tests/php_src/zip/prelude.php`;
//!   that PHP file is the provenance copy and is never parsed by the compiler.
//! - Every declaration is a separate helper so the builder stays within one stack frame.
//! - The bridge is what makes the surface optional; this module only declares the PHP shape.

use crate::parser::ast::{BinOp, CastType, CType, Program, Stmt, TypeExpr};
use crate::synthetic_class::{
    class, e_array, e_array_assoc, e_assign, e_binop, e_bool, e_call, e_cast, e_class_const,
    e_closure_call, e_const, e_float, e_index, e_int, e_method_call, e_neg, e_new, e_new_fq,
    e_not, e_null, e_null_coalesce, e_post_inc, e_prop, e_self_const, e_self_static_prop,
    e_static_call, e_static_prop, e_str, e_ternary, e_this, e_this_prop, e_var, extern_fn,
    function, internal_declarations, method, s_array_assign, s_array_push, s_assign, s_break,
    s_continue, s_expr, s_for, s_foreach, s_global, s_if, s_nested_array_assign, s_prop_assign, s_return,
    s_return_void, s_static_prop_array_assign, s_throw, s_try, s_while, t_array, t_class,
    t_mixed, t_nullable, t_union,
};

